abstract class TFMDataSourceBlock
{
    TFMPageDatasources	ds;
    TFMDocumentDeviceId deviceId;
    Map                 overrideFieldsMap;  


}

Method.Source:
public TFMDocumentDeviceId parmDeviceId(TFMDocumentDeviceId _deviceId = deviceId)
{
    deviceId = _deviceId;
    return deviceId;
}

public Map getOverrideFieldsMap()
{
    if(!overrideFieldsMap)
    {
        overrideFieldsMap = new Map(Types::String, Types::String);
    }
    return overrideFieldsMap;
}

	public Map AddFields(Common _common)
    {
        Map retMap = TFMGenericParms::makeParmsMapFromOverride(classId2Name(classidget(this)),ds.TableName + '/' + ds.OrderType,this);

        overrideFieldsMap = new Map(Types::String, Types::String);

        return retMap;
    }
